"use strict";(globalThis.webpackChunkgrc||=[]).push([[54241],{37015(e){e.exports=JSON.parse('{"citeKey":"sun2010reevaluatingamdahl","slug":"sun-2010-reevaluating-amdahl-8130","title":"Reevaluating Amdahl\'s Law in the Multicore Era","authors":["X.-H. Sun","Y. Chen"],"venue":"Journal of Parallel and Distributed Computing, vol. 70, no. 2, pp. 183-188","type":"Journal","entryType":"article","date":"February, 2010","year":2010,"era":"iit","month":2,"doi":"10.1016/j.jpdc.2009.05.002","abstract":"Microprocessor architecture has entered the multicore era. Recently, Hill and Marty presented a pessimistic view of multicore scalability. Their analysis was based on Amdahl\'s law (i.e. fixed-workload condition) and challenged readers to develop better models. In this study, we analyze multicore scalability under fixed-time and memory-bound conditions and from the data access (memory wall) perspective. We use the same hardware cost model of multicore chips used by Hill and Marty, but achieve very different and more optimistic performance models. These models show that there is no inherent, immovable upper bound on the scalability of multicore architectures. These results complement existing studies and demonstrate that multicore architectures are capable of extensive scalability.","hasAbstract":true,"lede":"Microprocessor architecture has entered the multicore era.","links":{"pdf":"https://grc.iit.edu/papers/2010/sun-2010-reevaluating-amdahl-8130.pdf","slides":"https://grc.iit.edu/papers/2010/sun-2010-reevaluating-amdahl-8130-slides.pdf"},"_projectIds":[],"grcSelected":false,"status":"published","visibility":"public","projectIds":[],"memberAuthors":["sun-xian-he"]}')}}]);